        _statusStrip = new StatusStrip();
        // .NET 9 breaking change: StatusStrip default renderer changed from System to
        // ManagerRenderMode. Explicitly set to preserve .NET 8 visual behavior.
        _statusStrip.RenderMode = ToolStripRenderMode.System;
        Controls.Add(_statusStrip);
