    /// Shows a dropdown editor, guarding against the .NET 9 breaking change where
    /// IWindowsFormsEditorService.DropDownControl now throws ArgumentNullException for null.
    /// </summary>
    public void ShowDropDown(IWindowsFormsEditorService editorService, Control? control)
    {
        if (control is null)
            return;

        editorService.DropDownControl(control);
    }
}

